var a=92;var i=[{id:`cooking-092-01`,theoryId:92,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What most directly helps raw vegetables remain crisp?`,ua:`Що найкраще допомагає сирим овочам залишатися хрусткими?`},explanation:{en:`Water-filled cells under pressure plus intact walls give crisp structure.`,ua:`Хрусткість забезпечують наповнені водою клітини з тургором та неушкоджені стінки.`},options:[{id:`a`,text:{en:`Intact cell walls and turgor pressure`,ua:`Цілісні клітинні стінки та тургор`}},{id:`b`,text:{en:`Completely dissolved pectin`,ua:`Повністю розчинений пектин`}},{id:`c`,text:{en:`Evaporated internal water`,ua:`Випарена внутрішня вода`}}],answer:{optionIds:[`a`]}},{id:`cooking-092-02`,theoryId:92,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Pectin helps cement neighboring plant cells together.`,ua:`Пектин допомагає з’єднувати сусідні рослинні клітини.`},explanation:{en:`Pectic materials contribute to cell adhesion and firmness.`,ua:`Пектинові речовини сприяють зчепленню клітин та щільності тканини.`},answer:{value:!0}},{id:`cooking-092-03`,theoryId:92,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match plant structures to culinary effects.`,ua:`Поєднайте частини рослинної клітини з кулінарними наслідками.`},explanation:{en:`Texture reflects both cell-wall integrity and cell water status.`,ua:`Текстура залежить від цілісності стінок і вмісту води в клітинах.`},leftItems:[{id:`l1`,text:{en:`Cell wall`,ua:`Клітинна стінка`}},{id:`l2`,text:{en:`Vacuole and turgor`,ua:`Вакуоля й тургор`}},{id:`l3`,text:{en:`Middle lamella pectin`,ua:`Пектин серединної пластинки`}}],rightItems:[{id:`r3`,text:{en:`Cell-to-cell adhesion`,ua:`Зчеплення між клітинами`}},{id:`r2`,text:{en:`Crispness of fresh produce`,ua:`Хрусткість свіжих овочів`}},{id:`r1`,text:{en:`Structural support`,ua:`Механічна опора`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-092-04`,theoryId:92,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Carrots become tender during simmering. What is the most likely structural reason?`,ua:`Морква стає м’якою під час варіння. Яка структурна причина найімовірніша?`},explanation:{en:`Heating changes adhesion between plant cells, allowing tissue to soften.`,ua:`Нагрівання змінює зчеплення клітин, тому тканина розм’якшується.`},options:[{id:`a`,text:{en:`Heat alters pectic substances and cell-wall behavior`,ua:`Тепло змінює пектинові речовини та властивості стінок`}},{id:`b`,text:{en:`Carrot cells turn into fat`,ua:`Клітини моркви перетворюються на жир`}},{id:`c`,text:{en:`All fiber evaporates`,ua:`Уся клітковина випаровується`}}],answer:{optionIds:[`a`]}},{id:`cooking-092-05`,theoryId:92,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which statement about plant cells is wrong?`,ua:`Яке твердження про рослинні клітини хибне?`},explanation:{en:`Pectin is a plant-cell-wall polysaccharide, not a muscle protein.`,ua:`Пектин — полісахарид рослинних клітинних стінок, а не м’язовий білок.`},options:[{id:`a`,text:{en:`Water status affects crispness`,ua:`Вміст води впливає на хрусткість`}},{id:`b`,text:{en:`Cell walls affect shape during cooking`,ua:`Клітинні стінки впливають на форму під час приготування`}},{id:`c`,text:{en:`Pectin is an animal muscle protein`,ua:`Пектин — це білок м’язової тканини тварин`}}],answer:{optionIds:[`c`]}}];var n={theoryId:92,exercises:i};export{n as default,i as exercises,a as theoryId};